SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion,
    payload_code AS payloadCode, payload_name AS payloadName, payload_json AS payloadJson,
    snapshot_time AS snapshotTime, create_time AS createTime, update_time AS updateTime
FROM diag_result_spec_json
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
ORDER BY payload_code ASC

SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion,
    payload_code AS payloadCode, payload_name AS payloadName, payload_json AS payloadJson,
    snapshot_time AS snapshotTime, create_time AS createTime, update_time AS updateTime
FROM diag_result_spec_json
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
  AND payload_code = #{payloadCode}

SELECT
    AVG(CAST(${metricColumn} AS DECIMAL(18, 6))) AS ave,
    MAX(${metricColumn}) AS maxData,
    MIN(${metricColumn}) AS minData,
    COUNT(1) AS total
FROM diag_result_spec_metric
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}

SELECT
    spec_no AS specNo,
    spec_name AS specName,
    ${metricColumn} AS data
FROM diag_result_spec_metric
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
ORDER BY ${metricColumn} ${orderType}, spec_no ASC
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY
